import type { CSSObject } from '@emotion/react';
import emotionStyled from '@emotion/styled';

import { theme } from '../../../theme';
import type { TextButtonSize } from './TextButton';

const textButtonSizes: Record<TextButtonSize, CSSObject> = {
  small: {
    fontSize: theme.fonts.fontSizes['2'],
    lineHeight: theme.fonts.lineHeights['3'],
  },
  medium: {
    fontSize: theme.fonts.fontSizes['3'],
    lineHeight: theme.fonts.lineHeights['6'],
  },
  large: {
    fontSize: theme.fonts.fontSizes['4'],
    lineHeight: theme.fonts.lineHeights['6'],
  },
};

export const StyledTextButton = emotionStyled('button', {
  shouldForwardProp: (propName) => !['$css', '$size'].includes(propName),
})<{ $css?: CSSObject; $size: TextButtonSize }>(({ $css, $size }) => ({
  all: 'unset',
  alignItems: 'center',
  color: theme.colors.interfaceLabelPrimary,
  cursor: 'pointer',
  display: 'flex',
  fontFamily: theme.fonts.paragraph,
  fontWeight: theme.fonts.fontWeights.medium,
  textAlign: 'left',
  '& > svg': {
    color: theme.colors.semanticInfoText,
  },
  '&:disabled': {
    color: theme.colors.interfaceLabelDisabled,
    cursor: 'unset',
    '& > svg': {
      color: theme.colors.interfaceLabelDisabled,
    },
  },
  '&:hover:not([disabled]) > svg': {
    color: theme.colors.interfaceLabelPrimary,
  },
  '&:active:not([disabled])': {
    color: theme.colors.interfaceLabelSecondary,
    '& > svg': {
      color: theme.colors.semanticInfoText,
    },
  },
  '&:focus-visible': {
    outline: 'auto',
  },
  ...textButtonSizes[$size],
  ...$css,
}));
